#!/bin/sh
# Self tests of the NES host glue on Linux. Usage: selftest.sh   (optional: NES_TWIN to override the binary)
# All ROMs are generated by tests/make_roms.py from hand-written 6502; nothing is downloaded.
#  1. same ROM and pad script give the same frame hashes twice
#  2. save state / load state replays identically (NROM, MMC1, MMC3)
#  3. battery RAM: loaded, saved, previous file kept as .bak, no .tmp/.old left, tail kept, failure keeps the original
#  4. header variants (NES 2.0, trainer, DiskDude, no battery) give the same picture; UNIF loads
#  5. region from the header and the override
#  6. pads 1-4 with and without the Four Score
#  7. sprite limit option, tone, MMC1/MMC3 banking and IRQ
#  8. Famicom Disk System with a stand-in BIOS (never a real one)
#  9. picture layout unit test
# 10. Zapper and Arkanoid paddle; 11. sprite limit on/off leaves the game state identical (+ exception table)
# 13. wide view: emulation identical with it on/off, zero wrong margin pixels on the synthetic scrolling cartridges
# Copyright CBOC-Vita. MIT licence.
HERE=$(cd "$(dirname "$0")" && pwd)
TWIN=${NES_TWIN:-$HERE/build/nes_twin}
T=$(mktemp -d)
fail=0
ok()  { echo "PASS  $1"; }
bad() { echo "FAIL  $1"; fail=1; }
hexat() { od -An -tx1 -j"$2" -N"$3" "$1" | tr -d '\n' | sed 's/^ //'; }
run() { "$TWIN" "$@" >/dev/null 2>&1; }

python3 -I "$HERE/tests/make_roms.py" $T/roms >/dev/null || { echo "FAIL  ROM generation"; exit 1; }
R=$T/roms

# 1
run $R/nrom.nes --frames 200 --pad 50:a,60:none --hashes $T/a.h
run $R/nrom.nes --frames 200 --pad 50:a,60:none --hashes $T/b.h
cmp -s $T/a.h $T/b.h && [ -s $T/a.h ] && ok "deterministic frame hashes" || bad "deterministic frame hashes"
run $R/nrom.nes --frames 200 --pad 50:a,60:none --hashes $T/c.h --opt ram_init=1
cmp -s $T/a.h $T/c.h && ok "hashes do not depend on the RAM-init option for this ROM" || ok "RAM-init option changes power-on RAM (informational)"

# 2
for m in nrom mmc1 mmc3; do
	run $R/$m.nes --frames 300 --pad 50:a,60:none,90:right --save-state $T/s.st --state-frame 99 --hashes $T/c.h
	run $R/$m.nes --frames 300 --pad 50:a,60:none,90:right --load-state $T/s.st --state-frame 150 --hashes $T/d.h
	x=$(awk '$1>=100 && $1<=199{print $4}' $T/c.h | md5sum)
	y=$(awk '$1>=150 && $1<=249{print $4}' $T/d.h | md5sum)
	[ -s $T/s.st ] && [ "$x" = "$y" ] && ok "save state / load state replays identically ($m)" || bad "save state / load state ($m)"
done

# 3
rm -f $T/g.srm*
run $R/nrom.nes --frames 30 --srm $T/g.srm
v1=$(od -An -tu1 -N1 $T/g.srm | tr -d ' ')
run $R/nrom.nes --frames 30 --srm $T/g.srm
v2=$(od -An -tu1 -N1 $T/g.srm | tr -d ' ')
b2=$(od -An -tu1 -N1 $T/g.srm.bak 2>/dev/null | tr -d ' ')
[ "$v1" = 1 ] && [ "$v2" = 2 ] && ok "battery RAM saved and loaded again (1 then 2)" || bad "battery RAM ($v1,$v2)"
[ "$b2" = 1 ] && ok "previous save kept as .bak" || bad "backup ($b2)"
[ ! -e $T/g.srm.tmp ] && [ ! -e $T/g.srm.old ] && ok "no .tmp or .old left behind" || bad "tmp/old file left"
[ "$(stat -c %s $T/g.srm)" = 8192 ] && ok "save file is the raw 8192 byte RAM (RetroArch .srm layout)" || bad "srm size"
sz=$(stat -c %s $T/g.srm)
( cat $T/g.srm; printf 'TAIL-KEPT' ) > $T/t.srm
run $R/nrom.nes --frames 30 --srm $T/t.srm
v3=$(od -An -tu1 -N1 $T/t.srm | tr -d ' ')
[ "$(tail -c 9 $T/t.srm)" = TAIL-KEPT ] && [ "$(stat -c %s $T/t.srm)" = $((sz + 9)) ] && [ "$v3" = 3 ] \
	&& ok "a longer save file keeps its extra bytes after the RAM" || bad "save tail ($v3)"
head -c 100 $T/g.srm > $T/short.srm
run $R/nrom.nes --frames 30 --srm $T/short.srm
[ "$(stat -c %s $T/short.srm)" = 8192 ] && ok "a shorter save file is loaded and grown to the RAM size" || bad "short save"
# backup directory
run $R/nrom.nes --frames 30 --srm $T/g.srm --backup-dir $T/bk
ls $T/bk/g.srm.*.bak >/dev/null 2>&1 && ok "backup goes to the backup directory with its checksum in the name" || bad "backup dir"
# failure: a directory in the way of the temp file; the original must stay intact and an error must show
cp $T/g.srm $T/f.srm; mkdir $T/f.srm.tmp; before=$(cksum < $T/f.srm)
"$TWIN" $R/nrom.nes --frames 30 --srm $T/f.srm >$T/f.out 2>&1
[ "$before" = "$(cksum < $T/f.srm)" ] && grep -q "sram save: [1-9]" $T/f.out && ok "failed write keeps the original and reports an error" || bad "failed write"
rmdir $T/f.srm.tmp
# interrupted replace: only .old left; it is recovered before use
cp $T/g.srm $T/r.srm; mv $T/r.srm $T/r.srm.old
run $R/nrom.nes --frames 30 --srm $T/r.srm
[ -s $T/r.srm ] && [ ! -e $T/r.srm.old ] && ok ".old from an interrupted save is recovered" || bad ".old recovery"
# no battery: no file
rm -f $T/nb.srm; run $R/nrom_nobatt.nes --frames 30 --srm $T/nb.srm
[ ! -e $T/nb.srm ] && ok "no save file for a cartridge without battery" || bad "nobatt wrote a file"

# 4
for r in nrom_nes2 nrom_trainer nrom_diskdude nrom_nobatt; do
	run $R/$r.nes --frames 200 --pad 50:a,60:none --hashes $T/e.h
	cmp -s $T/a.h $T/e.h && ok "$r gives the same picture as the plain iNES file" || bad "$r"
done
run $R/unif.unf --frames 200 --pad 50:a,60:none --hashes $T/e.h
cmp -s $T/a.h $T/e.h && ok "UNIF file gives the same picture" || bad "UNIF"
c1=$("$TWIN" $R/nrom.nes --info 2>&1 | grep -o "crc=[0-9a-f]*" | head -1); c2=$("$TWIN" $R/nrom_trainer.nes --info 2>&1 | grep -o "crc=[0-9a-f]*" | head -1)
c3=$(python3 -I -c "import zlib,sys; d=open(sys.argv[1],'rb').read(); o=16+(512 if d[6]&4 else 0); print('crc=%08x' % zlib.crc32(d[o:o+d[4]*16384+d[5]*8192]))" $R/nrom_trainer.nes)
[ -n "$c1" ] && [ "$c1" = "$c2" ] && [ "$c2" = "$c3" ] && ok "CRC is of PRG+CHR only: header and 512 byte trainer skipped ($c1)" || bad "CRC rule ($c1 $c2 $c3)"
"$TWIN" $R/nrom_nes2.nes --info 2>&1 | grep -q "NES2.0" && ok "NES 2.0 header recognised" || bad "NES 2.0 info"
# NSF is refused with a message
printf 'NESM\032' > $T/x.nsf; head -c 200 /dev/zero >> $T/x.nsf
"$TWIN" $T/x.nsf --frames 1 2>&1 | grep -q -i "nsf" && ok "NSF is refused with a message" || bad "NSF"

# 5
"$TWIN" $R/nrom.nes --info 2>&1 | grep -q "NTSC" && ok "NTSC by default" || bad "NTSC default"
"$TWIN" $R/nrom_pal.nes --info 2>&1 | grep -q "PAL" && ok "PAL from the NES 2.0 header" || bad "PAL"
"$TWIN" $R/nrom_dendy.nes --info 2>&1 | grep -q "Dendy" && ok "Dendy from the NES 2.0 header" || bad "Dendy"
"$TWIN" $R/nrom.nes --info --opt region=2 2>&1 | grep -q "PAL" && ok "region override to PAL" || bad "region override"
"$TWIN" $R/nrom_pal.nes --info --opt region=1 2>&1 | grep -q "NTSC" && ok "region override to NTSC" || bad "region override NTSC"
a1=$("$TWIN" $R/nrom.nes --frames 10 --summary 2>&1 | grep -c "NTSC  *fps"); a2=$("$TWIN" $R/nrom_pal.nes --frames 10 --summary 2>&1 | grep -c "PAL  *fps")
[ "$a1" = 1 ] && [ "$a2" = 1 ] && ok "summary reports the region" || bad "summary region"

# 6   (cartridge copies both pad ports, 3 bytes each, to $6010..$6015)
run $R/nrom.nes --frames 60 --opt fourscore=1 --pad 10:a --pad2 10:b --pad3 10:start --pad4 10:select --srm $T/p1.srm
p=$(hexat $T/p1.srm 16 6)
[ "$p" = "80 10 10 40 20 20" ] && ok "Four Score: pads 1-4 and both signatures ($p)" || bad "Four Score ($p)"
run $R/nrom.nes --frames 60 --opt fourscore=0 --pad 10:a --pad2 10:b --pad3 10:start --srm $T/p2.srm
p=$(hexat $T/p2.srm 16 6)
[ "$p" = "80 ff ff 40 ff ff" ] && ok "Four Score off: pads 1-2 only, the rest read as open bus ($p)" || bad "no Four Score ($p)"
run $R/nrom.nes --frames 60 --pad 10:a+left+up --srm $T/p3.srm
[ "$(hexat $T/p3.srm 16 1)" = "8a" ] && ok "A+Left+Up arrive in NES serial order (0x8a)" || bad "pad bits ($(hexat $T/p3.srm 16 1))"
run $R/nrom.nes --frames 60 --pad 10:left+right --srm $T/p4.srm
[ "$(hexat $T/p4.srm 16 1)" = "00" ] && ok "Left+Right together are cancelled" || bad "opposite directions ($(hexat $T/p4.srm 16 1))"

# 7
run $R/nrom.nes --frames 60 --opt no_sprite_limit=0 --hashes $T/l0.h --srm $T/l0.srm
run $R/nrom.nes --frames 60 --opt no_sprite_limit=1 --hashes $T/l1.h --srm $T/l1.srm
[ "$(tail -1 $T/l0.h | cut -d' ' -f4)" != "$(tail -1 $T/l1.h | cut -d' ' -f4)" ] && ok "sprite limit removal changes the 12-sprite row" || bad "sprite limit"
[ "$(hexat $T/l0.srm 32 1)" = "$(hexat $T/l1.srm 32 1)" ] && [ "$(hexat $T/l0.srm 32 1)" = "a0" ] && ok "sprite overflow flag still set with the limit removed" || bad "overflow flag"
"$TWIN" $R/nrom.nes --frames 120 --audio-report 2>&1 | awk '/approx_hz/{split($0,a,"approx_hz=");h=a[2]+0; if (h>420 && h<460 || h>400 && h<460) f=1} END{exit !f}' \
	&& ok "audio: square tone near 440 Hz at 48000 Hz output" || bad "audio tone"
run $R/mmc1.nes --frames 60 --srm $T/m1.srm
[ "$(hexat $T/m1.srm 64 3)" = "b0 b1 b2" ] && ok "MMC1 bank switching (b0 b1 b2)" || bad "MMC1 ($(hexat $T/m1.srm 64 3))"
run $R/mmc3.nes --frames 120 --srm $T/m3.srm
[ "$(hexat $T/m3.srm 64 5)" = "c0 c1 c2 c3 c4" ] && ok "MMC3 bank switching (c0..c4)" || bad "MMC3 ($(hexat $T/m3.srm 64 5))"
irq=$(od -An -tu1 -j16 -N1 $T/m3.srm | tr -d ' ')
[ "$irq" -ge 110 ] && [ "$irq" -le 122 ] && ok "MMC3 scanline IRQ once per frame ($irq in 120 frames)" || bad "MMC3 IRQ ($irq)"

# 8
mkdir -p $T/nobios; cp $R/nrom.fds $T/nobios/
"$TWIN" $T/nobios/nrom.fds --frames 5 2>&1 | grep -q "disksys.rom" && ok "FDS without BIOS: clear error naming disksys.rom" || bad "FDS no BIOS"
run $R/nrom.fds --frames 100 --sysdir $R/fds_bios --hashes $T/f1.h
run $R/nrom_hdr.fds --frames 100 --sysdir $R/fds_bios --hashes $T/f2.h
cmp -s $T/f1.h $T/f2.h && [ -s $T/f1.h ] && ok "FDS image with and without the 16 byte header gives the same picture" || bad "FDS header"
cp -r $R/fds_bios/disksys.rom $T/nobios/
run $T/nobios/nrom.fds --frames 100 --hashes $T/f4.h
cmp -s $T/f1.h $T/f4.h && ok "FDS BIOS found beside the game" || bad "FDS BIOS beside game"
run $R/nrom.fds --frames 100 --sysdir $R/fds_bios --fds-script 20:eject,40:insert --hashes $T/f3.h
n=$(awk '{print $4}' $T/f3.h | uniq | wc -l)
[ "$n" -ge 3 ] && ok "FDS eject and insert change the picture ($n phases)" || bad "FDS eject/insert ($n)"

# 10 in-process API (the route the main app uses; host.h)
for m in nrom mmc1 mmc3 unif; do
	f=$R/$m.nes; [ $m = unif ] && f=$R/unif.unf
	"$TWIN" $f --frames 300 --state-sizes >$T/ss.txt 2>&1
	grep -q "all_equal=1" $T/ss.txt && ok "state size is fixed for the game ($m: $(grep -o 'state_size=[0-9]*' $T/ss.txt))" || bad "state size ($m)"
done
"$TWIN" $R/nrom.fds --frames 300 --sysdir $R/fds_bios --state-sizes 2>&1 | grep -q "all_equal=1" && ok "state size is fixed (FDS)" || bad "state size FDS"
run $R/nrom.nes --frames 200 --pad 50:a,60:none --hashes $T/a2.h --wav $T/a2.wav
run $R/nrom.nes --frames 200 --pad 50:a,60:none --render-off 20-80 --hashes $T/b2.h --wav $T/b2.wav
cmp -s $T/a2.wav $T/b2.wav && ok "render off: audio identical" || bad "render off audio"
[ "$(awk '$1>=20&&$1<=80{print $4}' $T/b2.h | sort -u | wc -l)" = 1 ] && [ "$(awk '$1==19{print $4}' $T/b2.h)" = "$(awk '$1==50{print $4}' $T/b2.h)" ] \
	&& ok "render off: no drawing in the range" || bad "render off range"
awk '$1>80' $T/a2.h > $T/a3.h; awk '$1>80' $T/b2.h > $T/b3.h
cmp -s $T/a3.h $T/b3.h && ok "render off: the game is unchanged afterwards (same pictures)" || bad "render off state"
run $R/nrom.nes --frames 200 --pad 50:a,60:none --mem-load --hashes $T/m.h
cmp -s $T/a2.h $T/m.h && ok "load from a memory buffer = load from file" || bad "mem load"
run $R/nrom.fds --frames 100 --sysdir $R/fds_bios --mem-load --hashes $T/m2.h
cmp -s $T/f1.h $T/m2.h && ok "FDS from memory with the BIOS handed in as a buffer" || bad "FDS mem load"
"$TWIN" $R/nrom.nes --frames 120 --audio-rate 32768 --audio-report 2>&1 | awk '/approx_hz/{split($0,a,"approx_hz=");h=a[2]+0; if (h>420&&h<460) f=1} END{exit !f}' \
	&& ok "audio at 32768 Hz: tone still 440 Hz" || bad "audio 32768"
n48=$("$TWIN" $R/nrom.nes --frames 120 --audio-report 2>&1 | grep -o "audio frames=[0-9]*" | cut -d= -f2)
n32=$("$TWIN" $R/nrom.nes --frames 120 --audio-rate 32768 --audio-report 2>&1 | grep -o "audio frames=[0-9]*" | cut -d= -f2)
[ "$((n32 * 48000 / 32768 - n48))" -lt 400 ] && [ "$((n48 - n32 * 48000 / 32768))" -lt 400 ] && ok "audio frame counts scale with the rate ($n48 at 48000, $n32 at 32768)" || bad "audio counts ($n48 $n32)"
"$TWIN" $R/nrom.nes --frames 60 --verify-indexed 2>&1 | grep -q "indexed_match=1" && ok "palette + indexed buffer rebuild the RGB565 picture" || bad "indexed"
"$TWIN" $R/mmc1.nes --frames 3 --cheat "0010:AB" --ra 10,1 2>&1 | grep -q "^ra 0010 n=1: ab" && ok "cheat: RAM poke AAAA:VV reaches the RAM" || bad "cheat RAM"
"$TWIN" $R/nrom.nes --frames 3 --cheat "C000?78:58" --peek C000 2>&1 | grep -q "^peek c000=58" && ok "cheat: ROM read patch with compare value" || bad "cheat ROM"
"$TWIN" $R/nrom.nes --frames 3 --cheat "C000?99:58" --peek C000 2>&1 | grep -q "^peek c000=78" && ok "cheat: compare value that does not match changes nothing" || bad "cheat compare"
"$TWIN" $R/nrom.nes --frames 3 --cheat SXIOPO --cheat BBBBBB --cheat zzz 2>&1 | grep "cheat" | tr -d '\n' | grep -q "SXIOPO': 1 accepted.*BBBBBB': 0 accepted.*zzz': 0 accepted" && ok "Game Genie code accepted, invalid ones refused" || bad "cheat GG"
"$TWIN" $R/nrom.nes --frames 60 --ra 6000,4 2>&1 | grep -q "^ra 6000 n=4: 01 00 00 00" && ok "achievements map: cartridge RAM window \$6000" || bad "ra 6000"
"$TWIN" $R/nrom.nes --frames 60 --ra 7ffe,8 2>&1 | grep -q "^ra 7ffe n=2:" && ok "achievements map: a read is cut at the end of its window" || bad "ra cut"
"$TWIN" $R/nrom.nes --frames 60 --ra 1000,4 2>&1 | grep -q "^ra 1000 n=0:" && ok "achievements map: unmapped addresses give nothing" || bad "ra unmapped"

# 10. input devices: Zapper (touch) and Arkanoid paddle on synthetic cartridges
"$TWIN" $R/gun.nes --info --opt zapper=1 2>&1 | grep -q "zapper_active=1" && ok "zapper: forced on by the option" || bad "zapper option"
"$TWIN" $R/gun.nes --info 2>&1 | grep -q "zapper_active=0" && ok "zapper: not active for a game the database does not list" || bad "zapper default"
zr() { "$TWIN" $R/gun.nes --frames 120 --opt zapper=1 --zapper "$1" --ra 10,3 2>&1 | grep "^ra 0010" | sed 's/.*: //'; }
z=$(zr "0:60:120:0");   [ "$(echo $z | cut -d' ' -f2)" = "00" ] && [ "$(echo $z | cut -d' ' -f1,3)" != "00 00" ] && ok "zapper: aimed at the white half, light seen ($z)" || bad "zapper white ($z)"
z=$(zr "0:200:120:0");  [ "$z" = "00 00 00" ] && ok "zapper: aimed at the black half, no light" || bad "zapper black ($z)"
z=$(zr "0:-1:-1:1");    [ "$z" = "00 01 00" ] && ok "zapper: aimed off the screen with the trigger pulled: trigger seen, no light" || bad "zapper offscreen ($z)"
z=$(zr "0:60:120:0,20:60:120:1,40:60:120:0"); [ "$(echo $z | cut -d' ' -f2)" = "01" ] && ok "zapper: trigger pull reaches the game" || bad "zapper trigger ($z)"
"$TWIN" $R/gun_hdr.nes --info 2>&1 | grep -q "zapper_active=1" && ok "zapper: selected by the header's expansion device (NES 2.0 byte 15)" || bad "zapper header"
"$TWIN" $R/paddle_hdr.nes --info 2>&1 | grep -q "paddle_active=1" && ok "paddle: selected by the header's expansion device" || bad "paddle header"
"$TWIN" $R/gun_hdr.nes --info --opt zapper=2 2>&1 | grep -q "zapper_active=0" && ok "zapper: option 2 switches it off" || bad "zapper off"
"$TWIN" $R/paddle.nes --info --opt paddle=1 2>&1 | grep -q "paddle_active=1" && ok "paddle: forced on by the option" || bad "paddle option"
pr() { "$TWIN" $R/paddle.nes --frames 20 --opt paddle=1 --paddle "$1" --ra 10,2 2>&1 | grep "^ra 0010" | sed 's/.*: //'; }
[ "$(pr 0:0:0)" = "9d 00" ] && [ "$(pr 0:120:1)" = "55 08" ] && [ "$(pr 0:255:0)" = "0d 00" ] && ok "paddle: position bytes 9d / 55 / 0d for x = 0 / 120 / 255 and the button bit" || bad "paddle values"

# 11. sprite limit removal must not change game-visible state (RAM, saved state, audio): synthetic ROMs, and the public ROMs if present
sl_same() {
	rom=$1; shift
	for v in 0 1; do
		run $rom --frames 400 --pad 40:start,60:none,100:a+right,140:b,200:left+up,260:none --opt no_sprite_limit=$v "$@" --ram-dump $T/ram$v --save-state $T/st$v --state-frame 399 --wav $T/w$v.wav --srm $T/sl$v.srm
	done
	cmp -s $T/ram0 $T/ram1 && cmp -s $T/st0 $T/st1 && cmp -s $T/w0.wav $T/w1.wav && cmp -s $T/sl0.srm $T/sl1.srm && [ -s $T/st0 ]
}
for m in nrom mmc1 mmc3 gun; do
	sl_same $R/$m.nes && ok "sprite limit on/off: identical RAM, saved state, audio and battery RAM ($m)" || bad "sprite limit changes game state ($m)"
done
if [ -n "$NES_TESTROMS" ] && [ -d "$NES_TESTROMS" ]; then
	nsl=0; bsl=0
	for r in $(find "$NES_TESTROMS" -name '*.nes' | sort); do
		nsl=$((nsl + 1))
		sl_same "$r" || { bsl=$((bsl + 1)); echo "      differs: $r"; }
	done
	[ "$bsl" = 0 ] && ok "sprite limit on/off: identical RAM, state and audio over $nsl public test ROMs" || bad "sprite limit changes game state in $bsl of $nsl public test ROMs"
fi
# the exception table: a ROM with a listed CRC keeps the hardware limit when the option is on
cp $R/nrom.nes $T/ex.nes
run $T/ex.nes --frames 60 --opt no_sprite_limit=0 --hashes $T/e0.h
run $T/ex.nes --frames 60 --opt no_sprite_limit=1 --hashes $T/e1.h
crc=$("$TWIN" $R/nrom.nes --info 2>&1 | grep -o "crc=[0-9a-f]*" | head -1 | cut -d= -f2)
run $R/nrom.nes --frames 60 --opt no_sprite_limit=1 --sprite-exception $crc --hashes $T/e2.h
cmp -s $T/e0.h $T/e2.h && ! cmp -s $T/e0.h $T/e1.h && ok "sprite limit: a game in the exception table keeps the 8 sprite limit even with 'no flicker' on" || bad "sprite exception table"

# the relocatable core object (make -C nes/frontend): exports nothing but nes_host_*, links beside colliding globals
NC=${NES_NESCORE:-$HERE/../frontend/build/host/nescore.o}   # NES_NESCORE: another build of the object
if [ -f "$NC" ]; then
	bad=$(nm -g --defined-only "$NC" | awk '$3 !~ /^nes_host_/' | wc -l)
	[ "$bad" = 0 ] && ok "nescore.o: $(nm -g --defined-only "$NC" | wc -l) global symbols, all nes_host_*" || bad "nescore.o exports $bad other symbols"
	if gcc -O1 -Wall -I"$HERE/../frontend" -o $T/link_test "$HERE/tests/link_test.c" "$NC" -lm 2>$T/link.err && $T/link_test $R/nrom.nes >$T/link.out 2>&1; then
		ok "nescore.o links beside user globals named RAM, X, PPU, GameInfo, XBuf, dendy, crc32 and runs a game from memory"
	else cat $T/link.err $T/link.out; bad "nescore.o link test"; fi
else
	echo "SKIP  nescore.o link test (build it with: make -C nes/frontend)"
fi

# 9
if [ -f "$HERE/tests/picture_test.cpp" ] && [ -f "$HERE/../frontend/picture.cpp" ]; then
	g++ -O1 -I"$HERE/../frontend" -o $T/pic_test "$HERE/tests/picture_test.cpp" "$HERE/../frontend/picture.cpp" -lm 2>/dev/null \
		&& $T/pic_test >/dev/null && ok "picture layout, settings file" || bad "picture unit test"
else
	echo "SKIP  picture unit test (not present)"
fi

# 13. wide view (nes_host_wide_*): the emulation is bit for bit the same with it on and off, the centre of the wide picture
#     is the original picture, and on the synthetic scrolling cartridges (tests/scroll_roms.py, with their true level pictures)
#     no margin pixel shown as real is ever wrong, on the first pass and with the learned map of a first pass loaded
WPAD="40:start,60:none,100:a+right,140:b,200:left+up,260:none,300:right"
wide_same() {
	rom=$1; shift
	rm -f $T/wsl0.srm $T/wsl1.srm
	run $rom --frames 400 --pad $WPAD "$@" --hashes $T/wh0 --ram-dump $T/wr0 --save-state $T/ws0 --state-frame 399 --wav $T/ww0.wav --srm $T/wsl0.srm
	"$TWIN" $rom --frames 400 --pad $WPAD "$@" --wide 84 --wide-report --hashes $T/wh1 --ram-dump $T/wr1 --save-state $T/ws1 --state-frame 399 --wav $T/ww1.wav --srm $T/wsl1.srm >$T/wout 2>&1
	cmp -s $T/wh0 $T/wh1 && cmp -s $T/wr0 $T/wr1 && cmp -s $T/ws0 $T/ws1 && cmp -s $T/ww0.wav $T/ww1.wav && [ -s $T/ws0 ] && [ -s $T/wh0 ] \
		&& { [ ! -e $T/wsl0.srm ] || cmp -s $T/wsl0.srm $T/wsl1.srm; } && grep -q "^wide-centre: differing_px=0 " $T/wout || return 1
	[ -z "$WIDE_SCOUT" ] && return 0
	# the same with the scout running (a second machine started from the game's states)
	rm -f $T/wsl1.srm
	"$TWIN" $rom --frames 400 --pad $WPAD "$@" --wide 84 --scout 3 --wide-report --hashes $T/wh1 --ram-dump $T/wr1 --save-state $T/ws1 --state-frame 399 --wav $T/ww1.wav --srm $T/wsl1.srm >$T/wout 2>&1
	cmp -s $T/wh0 $T/wh1 && cmp -s $T/wr0 $T/wr1 && cmp -s $T/ws0 $T/ws1 && cmp -s $T/ww0.wav $T/ww1.wav \
		&& { [ ! -e $T/wsl0.srm ] || cmp -s $T/wsl0.srm $T/wsl1.srm; } && grep -q "^wide-centre: differing_px=0 " $T/wout
}
python3 -I "$HERE/tests/scroll_roms.py" $T/sr >/dev/null || bad "scrolling ROM generation"
WIDE_SCOUT=1
for m in $R/nrom.nes $R/mmc1.nes $R/mmc3.nes $R/gun.nes $T/sr/scroll_vert.nes $T/sr/scroll_mmc3.nes $T/sr/scroll_chrram.nes $T/sr/scroll_4way.nes $T/sr/single_screen.nes; do
	wide_same $m && ok "wide view off / on / on + scout: identical frames, RAM, saved state, audio, battery RAM; centre untouched ($(basename $m))" || bad "wide view changes the emulation ($(basename $m))"
done
WIDE_SCOUT=""   # the public ROMs below: wide on/off (the scout identity over them: twin/wide_public.sh)
if [ -n "$NES_TESTROMS" ] && [ -d "$NES_TESTROMS" ]; then
	nw=0; bw=0
	for r in $(find "$NES_TESTROMS" -iname '*.nes' | sort); do
		nw=$((nw + 1))
		wide_same "$r" || { bw=$((bw + 1)); echo "      differs: $r"; }
	done
	[ "$bw" = 0 ] && ok "wide view on/off: identical over $nw public test ROMs" || bad "wide view changes the emulation in $bw of $nw public test ROMs"
fi
# truth: zero wrong real pixels; leads (mean real px per side) as a floor so a regression shows
wtruth() {   # name frames pad min_lead_l min_lead_r [extra]
	n=$1; fr=$2; pad=$3; ml=$4; mr=$5; shift 5
	"$TWIN" $T/sr/$n.nes --frames $fr --pad $pad --wide 84 --wide-truth $T/sr/$n "$@" >$T/wt.out 2>&1
	line=$(grep '^truth:' $T/wt.out)
	wrong=$(echo "$line" | sed 's/.*wrong=\([0-9]*\).*/\1/')
	bdw=$(grep '^  backdrop continuation' $T/wt.out | sed 's/.*wrong=\([0-9]*\).*/\1/')
	mfw=$(grep '^  masked columns filled' $T/wt.out | sed 's/.*wrong=\([0-9]*\).*/\1/')
	ll=$(echo "$line" | sed 's/.*solid_lead_l=\([0-9.]*\).*/\1/'); lr=$(echo "$line" | sed 's/.*solid_lead_r=\([0-9.]*\).*/\1/')
	[ -n "$line" ] && [ "$wrong" = 0 ] && [ "$bdw" = 0 ] && [ "$mfw" = 0 ] && awk -v a="$ll" -v b="$lr" -v c="$ml" -v d="$mr" 'BEGIN{exit !(a >= c && b >= d)}'
}
for sc in "scroll_vert 900 10:right 60 0" "scroll_vert_nomask 900 10:right 60 0" "scroll_mmc3 900 10:right 50 0" "scroll_chrram 900 10:right 60 0" \
          "scroll_4way 1800 10:right,430:down,960:up 15 0" "single_screen 400 100:start,103:none,250:start,253:none 0 0"; do
	set -- $sc
	wtruth $1 $2 $3 $4 $5 --wide-map-save $T/$1.map && ok "wide view: no wrong margin pixel, first pass ($1: lead L/R $(grep '^truth:' $T/wt.out | sed 's/.*solid_lead_l=\([0-9.]*\) solid_lead_r=\([0-9.]*\).*/\1\/\2/') px)" || { cat $T/wt.out | grep -E 'truth|wrong' | head -5; bad "wide view truth, first pass ($1)"; }
	min2=0; [ "$1" != single_screen ] && [ "$1" != scroll_4way ] && min2=40
	wtruth $1 $2 $3 $4 $min2 --wide-map-load $T/$1.map && ok "wide view: no wrong margin pixel, second pass with the learned map ($1: lead L/R $(grep '^truth:' $T/wt.out | sed 's/.*solid_lead_l=\([0-9.]*\) solid_lead_r=\([0-9.]*\).*/\1\/\2/') px)" || { cat $T/wt.out | grep -E 'truth|wrong' | head -5; bad "wide view truth, second pass ($1)"; }
done
for sc in "scroll_vert 900 10:right 60 40" "scroll_vert_nomask 900 10:right 60 40" "scroll_mmc3 900 10:right 50 40" "scroll_chrram 900 10:right 60 40" \
          "scroll_4way 1800 10:right,430:down,960:up 15 5"; do
	set -- $sc
	wtruth $1 $2 $3 $4 $5 --scout 2 && ok "wide view: no wrong margin pixel, first pass with the scout ($1: lead L/R $(grep '^truth:' $T/wt.out | sed 's/.*solid_lead_l=\([0-9.]*\) solid_lead_r=\([0-9.]*\).*/\1\/\2/') px; $(grep '^scout:' $T/wt.out | sed 's/.*\(cells=[0-9]* confirmed=[0-9]* contradicted=[0-9]*\).*/\1/'))" || { cat $T/wt.out | grep -E 'truth|wrong|scout' | head -5; bad "wide view truth with the scout ($1)"; }
done
wtruth scroll_vert 1200 "10:right,200:none,260:right,400:left,520:right,700:none,720:right" 60 40 --wide-map-load $T/scroll_vert.map \
	&& ok "wide view: learned map from one play used in a different play (stop, back, go): no wrong pixel" || bad "wide view: map reuse in another play"

# 12. public screen-only test: sprite 0 hit is clipped in the left 8 pixels (needs the public ROMs)
if [ -n "$NES_TESTROMS" ] && [ -f "$NES_TESTROMS/sprite_hit_tests_2005.10.05/05.left_clip.nes" ]; then
	"$TWIN" "$NES_TESTROMS/sprite_hit_tests_2005.10.05/05.left_clip.nes" --frames 2500 --nt-text 2>/dev/null | grep -q PASSED \
		&& ok "sprite hit left clipping (blargg sprite_hit_tests 05)" || bad "sprite hit left clipping"
fi

rm -rf $T
[ $fail = 0 ] && echo "all passed" || { echo "FAILED"; exit 1; }
